/* Token Launch Radar — a dark, dense, data-first page.
   Palette: ink base, a single amber signal colour for value, cool grey for structure.
   No framework, no webfont fetch (the page renders offline): system stack only. */

:root {
  --ink: #0c0e13;
  --ink-2: #12151d;
  --ink-3: #191d28;
  --line: #242a38;
  --line-soft: #1c2130;
  --text: #e6e9f0;
  --text-dim: #98a1b5;
  --text-faint: #6a7389;
  --amber: #f5b544;
  --amber-dim: #a67c2c;
  --teal: #4fd1c5;
  --rose: #ef7183;
  --green: #6ee7a8;
  --radius: 10px;
  --mono: ui-monospace, "SF Mono", "Cascadia Mono", Menlo, Consolas, monospace;
  --sans: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
}

* { box-sizing: border-box; }

html, body {
  margin: 0;
  padding: 0;
  background: var(--ink);
  color: var(--text);
  font-family: var(--sans);
  font-size: 14.5px;
  line-height: 1.5;
  -webkit-font-smoothing: antialiased;
}

/* ---------- masthead ---------- */

.masthead {
  border-bottom: 1px solid var(--line);
  background: linear-gradient(180deg, #10131c 0%, var(--ink) 100%);
}

.masthead-inner {
  max-width: 1180px;
  margin: 0 auto;
  padding: 26px 24px 22px;
  display: flex;
  flex-wrap: wrap;
  gap: 22px;
  align-items: flex-start;
  justify-content: space-between;
}

.brand { display: flex; gap: 14px; align-items: flex-start; }

.brand-mark {
  width: 30px;
  height: 30px;
  flex: 0 0 30px;
  margin-top: 3px;
  border-radius: 50%;
  border: 2px solid var(--amber);
  position: relative;
  background:
    radial-gradient(circle at 50% 50%, var(--amber) 0 2px, transparent 2px),
    conic-gradient(from 0deg, transparent 0 78%, rgba(245, 181, 68, .55) 78% 100%);
}

.brand h1 {
  margin: 0;
  font-size: 21px;
  font-weight: 650;
  letter-spacing: -0.01em;
}

.tagline {
  margin: 3px 0 0;
  color: var(--text-dim);
  font-size: 13.5px;
  max-width: 52ch;
}

.headline {
  display: flex;
  gap: 26px;
  margin: 0;
  flex-wrap: wrap;
}

.headline div { min-width: 78px; }

.headline dt {
  color: var(--text-faint);
  font-size: 10.5px;
  text-transform: uppercase;
  letter-spacing: 0.09em;
  margin: 0 0 3px;
}

.headline dd {
  margin: 0;
  font-family: var(--mono);
  font-size: 17px;
  font-variant-numeric: tabular-nums;
  color: var(--amber);
}

.headline div:nth-child(n+3) dd { color: var(--text); font-size: 15px; }

/* ---------- method strip ---------- */

.method {
  border-bottom: 1px solid var(--line-soft);
  background: var(--ink-2);
}

.method-inner {
  max-width: 1180px;
  margin: 0 auto;
  padding: 18px 24px;
  display: grid;
  grid-template-columns: 1fr 340px;
  gap: 28px;
  align-items: center;
}

.method-copy h2 {
  margin: 0 0 6px;
  font-size: 13px;
  text-transform: uppercase;
  letter-spacing: 0.1em;
  color: var(--text-faint);
  font-weight: 600;
}

.method-copy p { margin: 0 0 6px; font-size: 13.5px; color: var(--text-dim); }
.method-copy #method-fit { font-size: 12.5px; color: var(--text-faint); }
.method-copy strong { color: var(--text); font-weight: 600; }
.method-copy code {
  font-family: var(--mono);
  font-size: 12.5px;
  background: var(--ink-3);
  border: 1px solid var(--line-soft);
  border-radius: 4px;
  padding: 1px 5px;
  color: var(--amber);
}

.method-curve { border-left: 1px solid var(--line-soft); padding-left: 22px; }
.curve-head {
  font-size: 10.5px;
  text-transform: uppercase;
  letter-spacing: 0.09em;
  color: var(--text-faint);
  margin-bottom: 4px;
}
.curve-note { margin: 2px 0 0; font-size: 11.5px; color: var(--text-faint); }
#curve { width: 100%; height: 118px; display: block; }

/* ---------- controls ---------- */

.controls {
  max-width: 1180px;
  margin: 0 auto;
  padding: 16px 24px 10px;
  display: flex;
  gap: 14px;
  flex-wrap: wrap;
  align-items: flex-end;
}

.control-group { display: flex; flex-direction: column; gap: 5px; }

.control-group label {
  font-size: 10.5px;
  text-transform: uppercase;
  letter-spacing: 0.09em;
  color: var(--text-faint);
}

.control-group input,
.control-group select {
  background: var(--ink-3);
  border: 1px solid var(--line);
  color: var(--text);
  border-radius: 7px;
  padding: 7px 10px;
  font-size: 13px;
  font-family: inherit;
  min-width: 150px;
  outline: none;
}

.control-group input:focus,
.control-group select:focus {
  border-color: var(--amber-dim);
  box-shadow: 0 0 0 2px rgba(245, 181, 68, 0.12);
}

#q { min-width: 230px; }

.ghost {
  background: transparent;
  border: 1px solid var(--line);
  color: var(--text-dim);
  border-radius: 7px;
  padding: 7px 14px;
  font-size: 12.5px;
  font-family: inherit;
  cursor: pointer;
  align-self: flex-end;
}

.ghost:hover { border-color: var(--amber-dim); color: var(--amber); }

/* ---------- board ---------- */

main {
  max-width: 1180px;
  margin: 0 auto;
  padding: 0 24px 40px;
}

.result-count {
  padding: 6px 0 12px;
  color: var(--text-faint);
  font-size: 12px;
  font-family: var(--mono);
}

table.board {
  width: 100%;
  border-collapse: collapse;
  font-size: 13.5px;
}

table.board thead th {
  text-align: left;
  font-size: 10.5px;
  text-transform: uppercase;
  letter-spacing: 0.08em;
  color: var(--text-faint);
  font-weight: 600;
  padding: 0 10px 9px;
  border-bottom: 1px solid var(--line);
  position: sticky;
  top: 0;
  background: var(--ink);
  z-index: 2;
}

table.board th.c-num, table.board td.c-num { text-align: right; }
table.board th.c-rank, table.board td.c-rank { width: 46px; text-align: right; color: var(--text-faint); }
table.board th.c-bar, table.board td.c-bar { width: 150px; }

table.board tbody tr {
  border-bottom: 1px solid var(--line-soft);
  cursor: pointer;
  transition: background 90ms ease;
}

table.board tbody tr:hover { background: var(--ink-2); }
table.board tbody tr.active { background: var(--ink-3); box-shadow: inset 2px 0 0 var(--amber); }

table.board td { padding: 9px 10px; vertical-align: middle; }

td.c-rank { font-family: var(--mono); font-size: 12.5px; }

td.c-name .nm { color: var(--text); font-weight: 550; }
td.c-name .sl { display: block; font-family: var(--mono); font-size: 11px; color: var(--text-faint); }

td.c-cat { color: var(--text-dim); font-size: 12.5px; }

td.c-num { font-family: var(--mono); font-variant-numeric: tabular-nums; font-size: 13px; }

.val { color: var(--amber); font-weight: 600; }
.mut { color: var(--text-dim); }
.pos { color: var(--green); }
.neg { color: var(--rose); }

.pill {
  display: inline-block;
  font-size: 9.5px;
  text-transform: uppercase;
  letter-spacing: 0.07em;
  padding: 1px 6px;
  border-radius: 4px;
  border: 1px solid var(--line);
  color: var(--text-faint);
  margin-left: 6px;
  vertical-align: 1px;
}
.pill.watch { border-color: var(--amber-dim); color: var(--amber); }

.bar-track {
  display: block;
  height: 6px;
  background: var(--ink-3);
  border-radius: 3px;
  overflow: hidden;
}
.bar-fill {
  display: block;
  height: 100%;
  background: linear-gradient(90deg, var(--amber-dim), var(--amber));
  border-radius: 3px;
}
.bar-label {
  display: block;
  margin-top: 3px;
  font-family: var(--mono);
  font-size: 10px;
  color: var(--text-faint);
  white-space: nowrap;
}

.empty { color: var(--text-faint); padding: 30px 0; text-align: center; }

/* ---------- detail panel ---------- */

.detail {
  position: fixed;
  top: 0;
  right: 0;
  width: min(520px, 94vw);
  height: 100vh;
  overflow-y: auto;
  background: var(--ink-2);
  border-left: 1px solid var(--line);
  box-shadow: -20px 0 60px rgba(0, 0, 0, 0.5);
  z-index: 40;
  padding: 26px 26px 60px;
}

.detail .close {
  position: absolute;
  top: 14px;
  right: 16px;
  width: 30px;
  height: 30px;
  border-radius: 6px;
  background: var(--ink-3);
  border: 1px solid var(--line);
  color: var(--text-dim);
  font-size: 18px;
  line-height: 1;
  cursor: pointer;
}

.detail .close:hover { color: var(--amber); border-color: var(--amber-dim); }

.detail h2 { margin: 0 0 2px; font-size: 19px; letter-spacing: -0.01em; }
.detail .d-slug { font-family: var(--mono); font-size: 12px; color: var(--text-faint); margin-bottom: 16px; }

.detail .d-chains { margin: 10px 0 18px; }
.detail .chain {
  display: inline-block;
  font-size: 11px;
  background: var(--ink-3);
  border: 1px solid var(--line-soft);
  border-radius: 5px;
  padding: 2px 7px;
  color: var(--text-dim);
  margin: 0 5px 5px 0;
}

.detail .d-value {
  padding: 14px 0 16px;
  border-top: 1px solid var(--line-soft);
  border-bottom: 1px solid var(--line-soft);
  margin-bottom: 18px;
}

.detail .d-value .big {
  font-family: var(--mono);
  font-size: 27px;
  color: var(--amber);
  font-variant-numeric: tabular-nums;
  line-height: 1.15;
}

.detail .d-value .sub { color: var(--text-faint); font-size: 12px; margin-top: 3px; }

.detail dl.d-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 12px 18px;
  margin: 0 0 22px;
}
.detail dl.d-grid div { min-width: 0; }
.detail dl.d-grid dt {
  font-size: 10.5px;
  text-transform: uppercase;
  letter-spacing: 0.08em;
  color: var(--text-faint);
  margin-bottom: 2px;
}
.detail dl.d-grid dd {
  margin: 0;
  font-family: var(--mono);
  font-size: 13px;
  font-variant-numeric: tabular-nums;
}

.detail h3 {
  font-size: 11px;
  text-transform: uppercase;
  letter-spacing: 0.1em;
  color: var(--text-faint);
  margin: 0 0 10px;
  font-weight: 600;
}

.detail ol.d-farm { margin: 0; padding-left: 0; list-style: none; counter-reset: step; }
.detail ol.d-farm li {
  counter-increment: step;
  position: relative;
  padding: 0 0 14px 30px;
  font-size: 13px;
  color: var(--text-dim);
  border-left: 1px solid var(--line-soft);
  margin-left: 9px;
}
.detail ol.d-farm li:last-child { padding-bottom: 0; border-left-color: transparent; }
.detail ol.d-farm li::before {
  content: counter(step);
  position: absolute;
  left: -9px;
  top: 0;
  width: 18px;
  height: 18px;
  border-radius: 50%;
  background: var(--ink-3);
  border: 1px solid var(--amber-dim);
  color: var(--amber);
  font-family: var(--mono);
  font-size: 10px;
  display: grid;
  place-items: center;
}

.detail .warn {
  margin-top: 18px;
  padding: 11px 13px;
  border-radius: 7px;
  background: rgba(239, 113, 131, 0.07);
  border: 1px solid rgba(239, 113, 131, 0.25);
  color: var(--rose);
  font-size: 12.5px;
}

/* ---------- colophon ---------- */

.colophon {
  border-top: 1px solid var(--line-soft);
  padding: 18px 24px 34px;
}
.colophon p {
  max-width: 1180px;
  margin: 0 auto;
  color: var(--text-faint);
  font-size: 11.5px;
  line-height: 1.6;
}

@media (max-width: 900px) {
  .method-inner { grid-template-columns: 1fr; }
  .method-curve { border-left: 0; border-top: 1px solid var(--line-soft); padding: 14px 0 0; }
  .headline { gap: 18px; }
  table.board th.c-bar, table.board td.c-bar { display: none; }
  .detail { width: 100vw; }
}
```

